private fun raised(name: String, path: String): ImageVector =
    ImageVector.Builder(name, 24.dp, 24.dp, 960f, 960f)
        .addGroup(translationY = 960f)
        .addPath(addPathNodes(path), fill = SolidColor(Color.Black))
        .clearGroup()
        .build()

